class Solution:
    def distributeCandies(self, n: int, limit: int) -> int:
        total = 0
        # For each possible amount to first child
        for first in range(limit + 1):
            remaining = n - first
            if remaining < 0:
                break

            # For the remaining candies, distribute to second and third child
            # We need to count pairs (second, third) such that second + third = remaining
            # with 0 <= second <= limit and 0 <= third <= limit
            if remaining == 0:
                total += 1
            else:
                # second can range from max(0, remaining - limit) to min(remaining, limit)
                min_second = max(0, remaining - limit)
                max_second = min(remaining, limit)

                if min_second <= max_second:
                    total += max_second - min_second + 1

        return total

